package com.yeyamo_mobile.api.interaction_service.infrastructure.persistence;
import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;
@Entity@Table(name="content_moderation_audit")public class ContentModerationAudit{@Id private UUID id;@Column(name="content_type",nullable=false)private String contentType;@Column(name="content_id",nullable=false)private UUID contentId;@Column(nullable=false)private String action;@Column(name="actor_id",nullable=false)private String actorId;@Column(length=1000)private String reason;@Column(name="correlation_id")private String correlationId;@Column(name="created_at",nullable=false)private Instant createdAt;protected ContentModerationAudit(){}public ContentModerationAudit(String t,UUID i,String a,String actor,String r,String c){id=UUID.randomUUID();contentType=t;contentId=i;action=a;actorId=actor;reason=r;correlationId=c;createdAt=Instant.now();}public String getAction(){return action;}public String getActorId(){return actorId;}public String getReason(){return reason;}public String getCorrelationId(){return correlationId;}public Instant getCreatedAt(){return createdAt;}}
